// entity 2
// Scripts-first trigger: it carries only its _tags handle. spawner-test.ts
// binds onTriggerEvent by this tag and fans out the door, spawn, and alarm
// reactions on the enter edge. No target_tag/command/on_fire KVP, so prl-build
// prints a benign [inert trigger] note it cannot resolve to the script observer.
{
"classname" "trigger_volume"
"_tags" "closet_reveal_plate"
// brush 0
{
( 112 16 0 ) ( 112 -48 16 ) ( 112 -48 0 ) debug_ceiling_grey 0 0 0 1 1
( 112 -48 16 ) ( 144 -48 0 ) ( 112 -48 0 ) debug_ceiling_grey 0 0 0 1 1
