( 112 16 16 ) ( 144 -48 16 ) ( 112 -48 16 ) debug_ceiling_grey 0 0 0 1 1
( 144 16 16 ) ( 112 16 16 ) ( 112 16 0 ) debug_ceiling_grey 0 0 0 1 1
( 144 -48 0 ) ( 144 16 16 ) ( 144 16 0 ) debug_ceiling_grey 0 0 0 1 1
}
}
// entity 3
// Scripts-first mover: only the KVPs with no scripting equivalent remain. path
// names the waypoint chain that is the motion geometry, speed tunes the slide
// (the mover command vocabulary carries no speed verb), and start_on_spawn 0
// holds the door shut until the script fires moverStart by _tags. The mover
// name is dropped; the script targets the door by tag, not by name.
{
"classname" "kinematic_mover"
"path" "closet_door_closed"
"speed" "4"
"start_on_spawn" "0"
"_tags" "closet_door"
// brush 0
