( 176 80 96 ) ( 160 80 96 ) ( 160 80 0 ) debug_ceiling_grey 0 0 0 1 1
( 176 -112 0 ) ( 176 -48 96 ) ( 176 -48 0 ) debug_ceiling_grey 0 0 0 1 1
}
}
