// entity 6
// Runtime spawner: the plate fires spawnFromSpawner, materializing count
// fresh reference_enemy AI enemies at this origin. count enemies fan out
// along the spawner local +X axis, spaced by the AI capsule diameter; keep
// the origin clear of the nook walls in that direction. archetype must name
// a registered AI-enemy canonical name; reference_enemy is globally
// registered by start-script.js.
{
"classname" "entity_spawner"
"origin" "224 -16 16"
"angles" "0 180 0"
"archetype" "reference_enemy"
"count" "3"
"_tags" "closet_spawner"
}
// entity 7
// Static red billboard-direct-scatter station. The player starts on the
// light-facing side with a clear path through x 80..120 to the lit emitter.
// Its matching smoke behind brush 10 remains in the spotlight cone but must be
// dark by occlusion; stepping sideways around the wall also exposes the cone
// edge. Keep this separate from the alarm below, which stays script-animated.
{
"classname" "light_spot"
"origin" "80 128 96"
"angles" "-50 0 0"
"_cone" "30"
"_cone2" "40"
"_falloff_range" "192"
"light" "500"
"_color" "255 0 0"
"_shadow_type" "static_light_map"
}
